-- 怀表 - 八哥延时

---@type ParkourGameUtil
local ParkourGameUtil = import("Game.Activity.ParkourGame.ParkourGameUtil")
---@type ParkourGameMgr
local Mgr = import("Game.Activity.ParkourGame.ParkourGameMgr"):GetInstance()

local Collider = CS.UnityEngine.Collider
local KTool = CS.Engine.Lib.KTool

local LuaParameters = CS.Engine.Modules.LuaParameters
---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

local CriWareUtils = import('Game.Entry.CriWareUtilsFix')

---@class Watch:TrackTriggerItem
local Watch = Class("Watch", import("Game.Activity.ParkourGame.MainGame.TrackItems.TrackTriggerItem"))


-- ==============================


function Watch:Awake()
    self.super.Awake(self)
    self.icon = self.controller.gameObject.transform:Find("icon")
    self.fx = self.controller.gameObject.transform:Find("fx")
    self.collider = KTool.GetComponent(self.controller.gameObject, typeof(Collider))
end


function Watch:Start()
    self.super.Start(self)
    local luaParams = CfUtils.GetOrAddComponent(self.controller.gameObject, typeof(LuaParameters))
    self.id = LuaParametersReader.Read(luaParams, "id", LuaParametersReader.Type.Int) -- 81001 这种

    self.events = CfUtils.EventsDecorated({
        [ParkourGameUtil.Events.BossCome]               = Bind(self, self.BossCome),
        [ParkourGameUtil.Events.BossLeave]              = Bind(self, self.BossLeave),
    })
end


-- 当 reset 来用:
function Watch:OnEnable()
    print("OnEnable")
    if Mgr.boss.showState == ParkourGameUtil.BossShowState.Show then 
        self:BossCome()
    else 
        self:BossLeave()
    end 
end


function Watch:OnDestroy()
    CfUtils.EventsUndecorated(self.events)
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- ====================================================


function Watch:Type()
    return ParkourGameUtil.TrackItemType.Watch
end

function Watch:PlayLogic(other)
    local isRole = other.name == Mgr.player.controller.gameObject.name
    if isRole == false then 
        return -- 不处理这个碰撞体
    end

    if Mgr.boss.showState == ParkourGameUtil.BossShowState.CountDown then
        Mgr.boss.appearTimer = Mgr.boss.appearTimer + ParkourGameUtil.Params.BossCountDownDelayTime -- 增加倒计时时长
    end
    Mgr:Add_Gain( self.id )
    CfUtils.SetActive(self.controller.gameObject,false)
    Mgr.player:SetRoleFX( "fx_Gain_get_blue", true, false, true )
end



function Watch:BossCome()
    self.collider.enabled = false
    CfUtils.SetActive( self.icon.gameObject, false )
    CfUtils.SetActive( self.fx.gameObject, false )
end

function Watch:BossLeave()
    self.collider.enabled = true
    CfUtils.SetActive( self.icon.gameObject, true )
    CfUtils.SetActive( self.fx.gameObject, true )
end


function Watch:PlayMusic()
    CriWareUtils.PlaySe( "Audio/sfx_instance_miniworld_parkour", "coin_get_12001801" )
end


return Watch